SELECT DISTINCTROW [Рабочий-для-ввода].NAME, [Рабочий-для-ввода].YEAR, [Рабочий-для-ввода].NUST, [Рабочий-для-ввода].E, [Рабочий-для-ввода].EOTP, [Рабочий-для-ввода].EURT, [Рабочий-для-ввода].EUST, [Рабочий-для-ввода].Q, [Рабочий-для-ввода].TURT, [Рабочий-для-ввода].TUST, [Рабочий-для-ввода].B, [Рабочий-для-ввода].GAZ, [Рабочий-для-ввода].MAZUT, [Рабочий-для-ввода].UGOL, [Рабочий-для-ввода].KUZN, [Рабочий-для-ввода].EKIB AS Выражение1, [Рабочий-для-ввода].URAL, [Рабочий-для-ввода].BASHK, [Рабочий-для-ввода].KARAG, [Рабочий-для-ввода].KAN, [Рабочий-для-ввода].TORF, [Рабочий-для-ввода].PROCH, [Рабочий-для-ввода].QOTR, [Рабочий-для-ввода].SNK, [Рабочий-для-ввода].EWTP, [Рабочий-для-ввода].NT, [Рабочий-для-ввода].NUMB1120, IIf([comp]=1,[numb],[main]) AS numbm, [Рабочий-для-ввода].SNt, Имена_станций.ordnumb, [Рабочий-для-ввода].NUMB1120
FROM [Рабочий-для-ввода] INNER JOIN Имена_станций ON [Рабочий-для-ввода].NUMB1120=Имена_станций.NUMB
WHERE ((([Рабочий-для-ввода].OES)=5))
ORDER BY Имена_станций.ordnumb;
